define(['uiComponent', 'Magento_Customer/js/customer-data', 'jquery', 'mage/url', 'Magento_Catalog/js/price-utils', 'mage/storage', 'ko', 'underscore', 'sidebar', 'mage/translate', 'mage/dropdown', ], function(Component, customerData, $, urlBuilder, priceUtils, storage, ko, _) {
    'use strict';
    var sidebarInitialized = false,
        addToCartCalls = 0,
        miniCart;
    var checkoutUrl = '';
    miniCart = $('[data-block=\'minicart\']');

    function initSidebar() {
        if (miniCart.data('mageSidebar')) {
            miniCart.sidebar('update');
        }
        if (!$('[data-role=product-item]').length) {
            return false;
        }
        miniCart.trigger('contentUpdated');
        if (sidebarInitialized) {
            return false;
        }
        sidebarInitialized = true;

        function getCheckoutUrl(callback) {
            $.ajax({
                url: urlBuilder.build('customizecheckout/address/defaultlist'),
                type: "GET",
                dataType: 'json',
                success: function(res) {
                    var isCheckoutUrl = res.hasAddresses ? window.checkout.checkoutUrl + '#payment' : window.checkout.checkoutUrl + '#shipping';
                    callback(isCheckoutUrl);
                }
            });
        }
        getCheckoutUrl(function(isCheckoutUrl) {
            checkoutUrl = isCheckoutUrl;
            miniCart.sidebar({
                'targetElement': 'div.block.block-minicart',
                'url': {
                    'checkout': checkoutUrl,
                    'update': window.checkout.updateItemQtyUrl,
                    'remove': window.checkout.removeItemUrl,
                    'loginUrl': window.checkout.customerLoginUrl,
                    'isRedirectRequired': window.checkout.isRedirectRequired
                },
                'button': {
                    'checkout': '#top-cart-btn-checkout',
                    'remove': '#mini-cart a.action.delete',
                    'close': '#btn-minicart-close'
                },
                'showcart': {
                    'parent': 'span.counter',
                    'qty': 'span.counter-number',
                    'label': 'span.counter-label'
                },
                'minicart': {
                    'list': '#mini-cart',
                    'content': '#minicart-content-wrapper',
                    'qty': 'div.items-total',
                    'subtotal': 'div.subtotal span.price',
                    'maxItemsVisible': window.checkout.minicartMaxItemsVisible
                },
                'item': {
                    'qty': ':input.cart-item-qty',
                    'button': ':button.update-cart-item'
                },
                'confirmMessage': $.mage.__('Are you sure you would like to remove this item from the shopping cart?')
            });
        });
    }

    function qtyControls() {
        $("#mini-cart").find('button.cart-qty-plus').unbind("click");
        $("#mini-cart button.cart-qty-plus").on("click", function() {
            var parent = $(this).parents('.details-qty');
            var $qval = parent.find("input.cart-item-qty");
            var a = $qval.val();
            a++;
            $qval.val(a);
            $qval.trigger("change");
            var productid = $qval.attr("data-cart-item");
            var productsku = $(this).attr("data-cart-item-id");
            var option = $(this).parents(".product-item-details").find(".product.options.list .values span").text();
            $.ajax({
                url: location.origin + '/eighteentech_ga4/checkout/getquotebysku',
                type: "POST",
                data: {
                    "is_mini": 1,
                    "productSku": productsku,
                    'option': option,
                    "qty": 1
                },
                dataType: 'json',
                success: function(res) {
                    var dataLayer = window.dataLayer || [];
                    var data = {
                        event: 'update_shopping_cart',
                        update_type: "add",
                        ecommerce: res.productObj
                    };
                    dataLayer.push({
                        ecommerce: null
                    });
                    dataLayer.push(data);
                }
            });
            $("#update-cart-item-" + productid).trigger("click");
            $("#update-cart-item-" + productid).hide();
        });
        $("#mini-cart").find('button.cart-qty-minus').unbind("click");
        $("#mini-cart button.cart-qty-minus").on("click", function() {
            var parent = $(this).parents('.details-qty');
            var $qval = parent.find("input.cart-item-qty");
            var b = $qval.val();
            if (b > 1) {
                b--;
                $qval.val(b);
                $qval.trigger("change");
                var productid = $qval.attr("data-cart-item");
                var productsku = $(this).attr("data-cart-item-id");
                var option = $(this).parents(".product-item-details").find(".product.options.list .values span").text();
                $.ajax({
                    url: location.origin + '/eighteentech_ga4/checkout/getquotebysku',
                    type: "POST",
                    data: {
                        "is_mini": 1,
                        "productSku": productsku,
                        'option': option,
                        "qty": 1
                    },
                    dataType: 'json',
                    success: function(res) {
                        var dataLayer = window.dataLayer || [];
                        var data = {
                            event: 'update_shopping_cart',
                            update_type: "remove",
                            ecommerce: res.productObj
                        };
                        dataLayer.push({
                            ecommerce: null
                        });
                        dataLayer.push(data);
                    }
                });
                $("#update-cart-item-" + productid).trigger("click");
                $("#update-cart-item-" + productid).hide();
            }
        });
    }
    miniCart.on('dropdowndialogopen', function() {
        initSidebar();
        qtyControls();
    });
    return Component.extend({
        shoppingCartUrl: window.checkout.shoppingCartUrl,
        maxItemsToDisplay: window.checkout.maxItemsToDisplay,
        cart: {},
        subtotal: ko.observable(0),
        mindiscount: ko.observable(0),
        grandtotal: ko.observable(0),
        offerTitle: ko.observable(0),
        crossellproducts: ko.observable(""),
        initialize: function() {
            var self = this,
                cartData = customerData.get('cart');
            this.update(cartData());
            if (cartData().items != undefined) {
                if (cartData().items.length != 0) {
                    self.getCartSubtotal();
                    self.getCrosseleProduct();
                }
            }
            cartData.subscribe(function(updatedCart) {
                addToCartCalls--;
                this.isLoading(addToCartCalls > 0);
                sidebarInitialized = false;
                this.update(updatedCart);
                initSidebar();
                qtyControls()
                self.getCartSubtotal();
                self.getCrosseleProduct();
            }, this);
            if (cartData().website_id !== window.checkout.websiteId && cartData().website_id !== undefined || cartData().storeId !== window.checkout.storeId && cartData().storeId !== undefined) {
                customerData.reload(['cart'], false);
            }
            return this._super();
        },
        isLoading: ko.observable(false),
        initSidebar: initSidebar,
        qtyControls: qtyControls,
        closeMinicart: function() {
            setTimeout(function() {
                $('[data-block="minicart"] [data-role="dropdownDialog"]').dropdownDialog('close');
            }, 200);
        },
        checkCusomerLogin: function(data, event) {
            location.href = window.checkout.shoppingCartUrl;
            event.preventDefault();
            return false;
        },
        getItemRenderer: function(productType) {
            return this.itemRenderer[productType] || 'defaultRenderer';
        },
        update: function(updatedCart) {
            _.each(updatedCart, function(value, key) {
                if (!this.cart.hasOwnProperty(key)) {
                    this.cart[key] = ko.observable();
                }
                this.cart[key](value);
            }, this);
        },
        getCartParamUnsanitizedHtml: function(name) {
            if (!_.isUndefined(name)) {
                if (!this.cart.hasOwnProperty(name)) {
                    this.cart[name] = ko.observable();
                }
            }
            return this.cart[name]();
        },
        getCartParam: function(name) {
            return this.getCartParamUnsanitizedHtml(name);
        },
        getCartItems: function() {
            var items = this.getCartParamUnsanitizedHtml('items') || [];
            items = items.slice(parseInt(-this.maxItemsToDisplay, 10));
            return items;
        },
        getCartLineItemsCount: function() {
            var items = this.getCartParamUnsanitizedHtml('items') || [];
            return parseInt(items.length, 10);
        },
        getFormattedPrice: function(price) {
            var priceFormat = {
                decimalSymbol: '.',
                groupLength: 3,
                groupSymbol: ",",
                integerRequired: false,
                pattern: "$%s",
                precision: 2,
                requiredPrecision: 2
            };
            return priceUtils.formatPrice(price, priceFormat);
        },
        getCrosseleProduct: function() {
            var self = this;
            var html = "";
            $.ajax({
                url: urlBuilder.build('ajaxmincart/ajax/crosssellproducts'),
                method: "POST",
                dataType: "json"
            }).done(function(response) {
                self.crossellproducts(response.html)
            });
            return html;
        },
        getCartSubtotal: function(callback) {
            var totalcartamt = this.cart.subtotalAmount();
            var self = this;
            var cartItems = self.getCartItems();
            var totalItems = cartItems.length;
            var subtotal = 0;
            var discountValue = 0;
            var completedRequests = 0;
            if (totalItems === 0) {
                self.subtotal(0);
                self.mindiscount(0);
                self.grandtotal(0);
                return;
            }
            cartItems.forEach(function(item) {
                var sku = item.product_sku;
                var requestUrl = urlBuilder.build('quickviewconfig/product/loadproduct');
                $.ajax({
                    url: requestUrl,
                    data: {
                        sku: sku,
                        is_min: 1
                    },
                    dataType: 'json',
                    success: function(response) {
                        if (response && response.price) {
                            subtotal += item.qty * response.price;
                            discountValue += item.qty * (response.price - item.product_price_value);
                        }
                    },
                    error: function() {
                        console.error('Failed to fetch price for SKU:', sku);
                    },
                    complete: function() {
                        completedRequests++;
                        if (completedRequests === totalItems) {
                            var priceFormat = {
                                decimalSymbol: '.',
                                groupLength: 3,
                                groupSymbol: ",",
                                integerRequired: false,
                                pattern: "₹%s",
                                precision: 2,
                                requiredPrecision: 2
                            };
                            self.subtotal(priceUtils.formatPrice(subtotal, priceFormat));
                            self.grandtotal(priceUtils.formatPrice(subtotal - discountValue, priceFormat))
                            self.mindiscount(priceUtils.formatPrice(discountValue, priceFormat))
                        }
                    }
                });
            });
        },
        getDiscountAmount: function() {
            return 20;
        },
        getCartGrandtotal: function() {
            return this.cart.subtotal_excl_tax();
        },
        offerTitle: function() {
            return window.checkout.offerTitle;
        }
    });
});